//! A question to a person is a recorded state, not a text marker in a comment (AWTD-1687).
//!
//! Until now an agent asked by writing a Decision comment that ended with `AGENT-HANDBACK:
//! <mailbox>` and reassigning the task, and the server found the answer by parsing that line.
//! These rules make the open question a fact the task carries, so the board can list "questions
//! waiting on me" without reading comments. **Canonical here**, core-first, with its fixture
//! `contracts/fixtures/questions.json` generated by `cargo xtask gen-core-contracts`.
//!
//! The asker and the answerer are each a user id — an agent is a user — so a person may ask an
//! agent and one agent may ask another.
//!
//! ## Q1 — asking
//!
//! [`ask`] records who asked, who must answer, the question comment and what the asker needs to
//! resume, and answers the hand-back write of [`crate::waiting::hand_back`] (R4: Inbox, assigned
//! to the answerer). The lane the task was in is remembered as [`Question::return_status_role`]:
//! `doing` when the asker held it in Doing, otherwise `ready`. A finished task cannot be asked
//! about, a task has at most one open question, and nobody asks themselves.
//!
//! ## Q2 — answering
//!
//! [`answer`] closes the question when the **answerer** replies (or taps a Decision card) and
//! returns the task to the asker in the remembered lane. A reply from anyone else is only a
//! comment: it is refused here and the question stays open. If the task was finished meanwhile
//! the question closes and nothing is written to the task. A reply is **not** approval to apply a
//! migration or release — that stays the orchestration policy's job.
//!
//! ## Q3 — resuming
//!
//! [`resume`] records that the asker picked the answer up, so it stops being attention.
//!
//! ## Q4 — who is waiting on whom
//!
//! [`attention`] answers, for one person, the open questions they must answer (oldest first) and
//! the answered ones they asked and have not resumed. It is what the agent queue's `attention`
//! and a "questions waiting on me" view read, across every list.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use crate::board::READY_STATUS_ROLE;
use crate::model::{date, Task};
use crate::waiting::{hand_back, HandBack};

/// The Doing lane's role, where an asker that held the task in Doing gets it back.
const DOING_STATUS_ROLE: &str = "doing";

pub const QUESTION_TASK_DONE: &str = "QUESTION_TASK_DONE";
pub const QUESTION_ALREADY_OPEN: &str = "QUESTION_ALREADY_OPEN";
pub const QUESTION_NEEDS_ANSWERER: &str = "QUESTION_NEEDS_ANSWERER";
pub const QUESTION_NEEDS_COMMENT: &str = "QUESTION_NEEDS_COMMENT";
pub const QUESTION_NOT_OPEN: &str = "QUESTION_NOT_OPEN";
pub const QUESTION_NOT_ANSWERER: &str = "QUESTION_NOT_ANSWERER";
pub const QUESTION_NOT_ANSWERED: &str = "QUESTION_NOT_ANSWERED";

/// One question on one task, as the server stores it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(rename_all = "camelCase")]
pub struct Question {
    pub task_id: String,
    pub asker_id: String,
    pub answerer_id: String,
    /// The Decision-format comment that carries the question text.
    pub question_comment_id: String,
    /// What the asker needs to pick the work up again, in the asker's own words.
    #[serde(default)]
    pub resume: String,
    /// `ready` or `doing`: where the task goes back to when the question is answered.
    pub return_status_role: String,
    #[cfg_attr(feature = "schema", schemars(with = "date::Timestamp"))]
    #[serde(with = "date::required")]
    pub asked_at: DateTime<Utc>,
    #[cfg_attr(feature = "schema", schemars(with = "Option<date::Timestamp>"))]
    #[serde(
        default,
        with = "date::optional",
        skip_serializing_if = "Option::is_none"
    )]
    pub answered_at: Option<DateTime<Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub answer_comment_id: Option<String>,
    #[cfg_attr(feature = "schema", schemars(with = "Option<date::Timestamp>"))]
    #[serde(
        default,
        with = "date::optional",
        skip_serializing_if = "Option::is_none"
    )]
    pub resumed_at: Option<DateTime<Utc>>,
}

/// Where a question is in its life.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum State {
    /// Asked; the answerer has not replied.
    Open,
    /// Answered; the asker has not picked it up.
    Answered,
    /// The asker resumed.
    Resumed,
}

impl Question {
    pub fn state(&self) -> State {
        match (self.answered_at, self.resumed_at) {
            (None, _) => State::Open,
            (Some(_), None) => State::Answered,
            (Some(_), Some(_)) => State::Resumed,
        }
    }
}

/// Why a question rule refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum QuestionError {
    #[serde(rename = "QUESTION_TASK_DONE")]
    TaskDone,
    #[serde(rename = "QUESTION_ALREADY_OPEN")]
    AlreadyOpen,
    #[serde(rename = "QUESTION_NEEDS_ANSWERER")]
    NeedsAnswerer,
    #[serde(rename = "QUESTION_NEEDS_COMMENT")]
    NeedsComment,
    #[serde(rename = "QUESTION_NOT_OPEN")]
    NotOpen,
    #[serde(rename = "QUESTION_NOT_ANSWERER")]
    NotAnswerer,
    #[serde(rename = "QUESTION_NOT_ANSWERED")]
    NotAnswered,
}

impl QuestionError {
    pub fn code(self) -> &'static str {
        match self {
            QuestionError::TaskDone => QUESTION_TASK_DONE,
            QuestionError::AlreadyOpen => QUESTION_ALREADY_OPEN,
            QuestionError::NeedsAnswerer => QUESTION_NEEDS_ANSWERER,
            QuestionError::NeedsComment => QUESTION_NEEDS_COMMENT,
            QuestionError::NotOpen => QUESTION_NOT_OPEN,
            QuestionError::NotAnswerer => QUESTION_NOT_ANSWERER,
            QuestionError::NotAnswered => QUESTION_NOT_ANSWERED,
        }
    }

    pub fn message(self) -> &'static str {
        match self {
            QuestionError::TaskDone => "A finished task cannot be asked about",
            QuestionError::AlreadyOpen => "This task already has an open question",
            QuestionError::NeedsAnswerer => "A question needs someone else to answer it",
            QuestionError::NeedsComment => "A question needs the comment that asks it",
            QuestionError::NotOpen => "This question is not open",
            QuestionError::NotAnswerer => "Only the person asked can answer this question",
            QuestionError::NotAnswered => "This question has not been answered",
        }
    }
}

/// Q1: what asking a question is.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(rename_all = "camelCase")]
pub struct Ask {
    pub asker_id: String,
    pub answerer_id: String,
    pub question_comment_id: String,
    #[serde(default)]
    pub resume: String,
}

/// Q1: the question to store and the hand-back write that goes with it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AskPlan {
    pub question: Question,
    pub write: HandBack,
}

/// Q1: ask about `task`, which has `open` as its latest question if it has one.
pub fn ask(
    task: &Task,
    open: Option<&Question>,
    request: &Ask,
    now: DateTime<Utc>,
) -> Result<AskPlan, QuestionError> {
    if task.completed {
        return Err(QuestionError::TaskDone);
    }
    if open.is_some_and(|held| held.state() == State::Open) {
        return Err(QuestionError::AlreadyOpen);
    }
    if request.answerer_id.is_empty() || request.answerer_id == request.asker_id {
        return Err(QuestionError::NeedsAnswerer);
    }
    if request.question_comment_id.is_empty() {
        return Err(QuestionError::NeedsComment);
    }
    let return_status_role = match task.status_role.as_deref() {
        Some(DOING_STATUS_ROLE) => DOING_STATUS_ROLE,
        _ => READY_STATUS_ROLE,
    };
    Ok(AskPlan {
        question: Question {
            task_id: task.id.clone(),
            asker_id: request.asker_id.clone(),
            answerer_id: request.answerer_id.clone(),
            question_comment_id: request.question_comment_id.clone(),
            resume: request.resume.clone(),
            return_status_role: return_status_role.to_string(),
            asked_at: now,
            answered_at: None,
            answer_comment_id: None,
            resumed_at: None,
        },
        write: hand_back(&request.answerer_id),
    })
}

/// Q2: the task's write when a question is answered — back to the asker in the remembered lane.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ReturnWrite {
    pub status_role: String,
    pub assignee_id: String,
    pub completed: bool,
}

/// Q2: the closed question, and the write returning the task (none when it was finished meanwhile).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AnswerPlan {
    pub question: Question,
    pub write: Option<ReturnWrite>,
}

/// Q2: `replier_id` answered `question` with `answer_comment_id`; `task_completed` is the task now.
pub fn answer(
    question: &Question,
    task_completed: bool,
    replier_id: &str,
    answer_comment_id: &str,
    now: DateTime<Utc>,
) -> Result<AnswerPlan, QuestionError> {
    if question.state() != State::Open {
        return Err(QuestionError::NotOpen);
    }
    if replier_id != question.answerer_id {
        return Err(QuestionError::NotAnswerer);
    }
    let closed = Question {
        answered_at: Some(now),
        answer_comment_id: Some(answer_comment_id.to_string()).filter(|id| !id.is_empty()),
        ..question.clone()
    };
    let write = (!task_completed).then(|| ReturnWrite {
        status_role: question.return_status_role.clone(),
        assignee_id: question.asker_id.clone(),
        completed: false,
    });
    Ok(AnswerPlan {
        question: closed,
        write,
    })
}

/// Q3: the asker picked the answer up.
pub fn resume(question: &Question, now: DateTime<Utc>) -> Result<Question, QuestionError> {
    match question.state() {
        State::Open => Err(QuestionError::NotAnswered),
        State::Answered => Ok(Question {
            resumed_at: Some(now),
            ..question.clone()
        }),
        State::Resumed => Ok(question.clone()),
    }
}

/// Q4: what one person has to do about questions. Ids are the task ids, oldest question first.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Attention {
    /// Open questions this person must answer.
    pub waiting_on_me: Vec<String>,
    /// Answered questions this person asked and has not resumed.
    pub to_resume: Vec<String>,
}

/// Q4: [`Attention`] for `person_id` over `questions`, from any list.
pub fn attention(questions: &[Question], person_id: &str) -> Attention {
    let pick = |wanted: State, mine: &dyn Fn(&Question) -> bool| {
        let mut found: Vec<&Question> = questions
            .iter()
            .filter(|held| held.state() == wanted && mine(held))
            .collect();
        found.sort_by(|a, b| {
            a.asked_at
                .cmp(&b.asked_at)
                .then_with(|| a.task_id.cmp(&b.task_id))
        });
        found
            .into_iter()
            .map(|held| held.task_id.clone())
            .collect::<Vec<_>>()
    };
    Attention {
        waiting_on_me: pick(State::Open, &|held| held.answerer_id == person_id),
        to_resume: pick(State::Answered, &|held| held.asker_id == person_id),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn at(text: &str) -> DateTime<Utc> {
        date::parse(text).expect("an instant")
    }

    const NOW: &str = "2026-11-16T12:00:00Z";

    fn task(role: &str) -> Task {
        Task {
            status_role: Some(role.to_string()),
            ..Task::new("t", "t")
        }
    }

    fn request() -> Ask {
        Ask {
            asker_id: "agent".into(),
            answerer_id: "jon".into(),
            question_comment_id: "c1".into(),
            resume: "re-run the gate".into(),
        }
    }

    fn open() -> Question {
        ask(&task("doing"), None, &request(), at(NOW))
            .expect("asks")
            .question
    }

    fn answered() -> Question {
        answer(&open(), false, "jon", "c2", at(NOW))
            .expect("answers")
            .question
    }

    #[test]
    fn asking_hands_the_task_to_the_answerer_and_remembers_the_lane_awtd_1687() {
        let plan = ask(&task("doing"), None, &request(), at(NOW)).unwrap();
        assert_eq!(plan.write, hand_back("jon"));
        assert_eq!(plan.question.return_status_role, "doing");
        assert_eq!(plan.question.state(), State::Open);
        let from_ready = ask(&task("ready"), None, &request(), at(NOW)).unwrap();
        assert_eq!(from_ready.question.return_status_role, "ready");
        let from_testing = ask(&task("testing"), None, &request(), at(NOW)).unwrap();
        assert_eq!(from_testing.question.return_status_role, "ready");
    }

    #[test]
    fn asking_is_refused_when_it_cannot_be_answered_awtd_1687() {
        let done = Task {
            completed: true,
            ..task("doing")
        };
        assert_eq!(
            ask(&done, None, &request(), at(NOW)),
            Err(QuestionError::TaskDone)
        );
        assert_eq!(
            ask(&task("doing"), Some(&open()), &request(), at(NOW)),
            Err(QuestionError::AlreadyOpen)
        );
        let myself = Ask {
            answerer_id: "agent".into(),
            ..request()
        };
        assert_eq!(
            ask(&task("doing"), None, &myself, at(NOW)),
            Err(QuestionError::NeedsAnswerer)
        );
        let blank = Ask {
            question_comment_id: String::new(),
            ..request()
        };
        assert_eq!(
            ask(&task("doing"), None, &blank, at(NOW)),
            Err(QuestionError::NeedsComment)
        );
    }

    #[test]
    fn a_new_question_may_follow_an_answered_one_awtd_1687() {
        assert!(ask(&task("doing"), Some(&answered()), &request(), at(NOW)).is_ok());
    }

    #[test]
    fn the_answerers_reply_returns_the_task_to_the_asker_awtd_1687() {
        let plan = answer(&open(), false, "jon", "c2", at("2026-11-16T13:00:00Z")).unwrap();
        assert_eq!(plan.question.state(), State::Answered);
        assert_eq!(plan.question.answer_comment_id.as_deref(), Some("c2"));
        assert_eq!(
            plan.write,
            Some(ReturnWrite {
                status_role: "doing".into(),
                assignee_id: "agent".into(),
                completed: false
            })
        );
    }

    #[test]
    fn only_the_answerer_closes_a_question_awtd_1687() {
        assert_eq!(
            answer(&open(), false, "ana", "c2", at(NOW)),
            Err(QuestionError::NotAnswerer)
        );
        assert_eq!(
            answer(&answered(), false, "jon", "c3", at(NOW)),
            Err(QuestionError::NotOpen)
        );
    }

    #[test]
    fn answering_a_finished_task_writes_nothing_to_it_awtd_1687() {
        let plan = answer(&open(), true, "jon", "c2", at(NOW)).unwrap();
        assert_eq!(plan.write, None);
        assert_eq!(plan.question.state(), State::Answered);
    }

    #[test]
    fn resuming_needs_an_answer_and_is_idempotent_awtd_1687() {
        assert_eq!(resume(&open(), at(NOW)), Err(QuestionError::NotAnswered));
        let resumed = resume(&answered(), at("2026-11-16T14:00:00Z")).unwrap();
        assert_eq!(resumed.state(), State::Resumed);
        assert_eq!(
            resume(&resumed, at("2026-11-17T00:00:00Z")).unwrap(),
            resumed
        );
    }

    #[test]
    fn attention_lists_what_a_person_must_answer_and_resume_awtd_1687() {
        let older = Question {
            task_id: "b".into(),
            asked_at: at("2026-11-15T00:00:00Z"),
            ..open()
        };
        let newer = Question {
            task_id: "a".into(),
            asked_at: at("2026-11-16T00:00:00Z"),
            ..open()
        };
        let waiting_for_asker = Question {
            task_id: "c".into(),
            ..answered()
        };
        let resumed = Question {
            task_id: "d".into(),
            ..resume(&answered(), at(NOW)).unwrap()
        };
        let all = [newer, older, waiting_for_asker, resumed];
        assert_eq!(
            attention(&all, "jon"),
            Attention {
                waiting_on_me: vec!["b".into(), "a".into()],
                to_resume: vec![]
            }
        );
        assert_eq!(
            attention(&all, "agent"),
            Attention {
                waiting_on_me: vec![],
                to_resume: vec!["c".into()]
            }
        );
    }
}
